local function IsEnemy(plr)
    if not plr or plr==Player then return false end
    if Player.Team and plr.Team then return Player.Team~=plr.Team end
    if Player.TeamColor and plr.TeamColor then return Player.TeamColor~=plr.TeamColor end
    return true
end

local function GetAimTarget()
    local best,bestScore=nil,math.huge
    local center=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y/2)
    for _,plr in ipairs(game:GetService("Players"):GetPlayers()) do
        if IsEnemy(plr) and plr.Character then
            local hum=plr.Character:FindFirstChildOfClass("Humanoid")
            local head=plr.Character:FindFirstChild("Head")
            if hum and hum.Health>0 and head then
                local pos,onScreen=Camera:WorldToViewportPoint(head.Position)
                if onScreen and pos.Z>0 then
                    local d=(Vector2.new(pos.X,pos.Y)-center).Magnitude
                    if d<=vars.aimbotFOV and d<bestScore then best,bestScore=plr,d end
                end
            end
        end
    end
    return best
end

local function Aimbot()
    task.spawn(function()
        while states.aimbot do
            pcall(function()
                local target=GetAimTarget()
                if target and target.Character then
                    local head=target.Character:FindFirstChild("Head") or target.Character:FindFirstChild("HumanoidRootPart")
                    if head then Camera.CFrame=Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.Position,head.Position),0.22) end
                end
            end)
            RunService.RenderStepped:Wait()
        end
    end)
end

