local ESPCache = {}

local function RemoveESP(plr)
    local e=ESPCache[plr]
    if e then
        pcall(function() if e.highlight then e.highlight:Destroy() end end)
        pcall(function() if e.billboard then e.billboard:Destroy() end end)
        ESPCache[plr]=nil
    end
end

local function UpdatePlayerESP(plr)
    if plr==Player then return end
    local char=plr.Character
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    local head=char and char:FindFirstChild("Head")
    if not char or not hum or not head then RemoveESP(plr) return end
    local e=ESPCache[plr]
    if not e then
        e={}
        e.highlight=Instance.new("Highlight")
        e.highlight.Name="ESP_Highlight"
        e.highlight.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
        e.highlight.Parent=char
        e.billboard=Instance.new("BillboardGui")
        e.billboard.Name="ESP_Info"
        e.billboard.Size=UDim2.new(0,190,0,34)
        e.billboard.StudsOffset=Vector3.new(0,2.7,0)
        e.billboard.AlwaysOnTop=true
        e.billboard.Parent=head
        e.label=Instance.new("TextLabel")
        e.label.Size=UDim2.fromScale(1,1)
        e.label.BackgroundTransparency=1
        e.label.Font=Enum.Font.GothamBold
        e.label.TextSize=12
        e.label.TextStrokeTransparency=0.35
        e.label.Parent=e.billboard
        ESPCache[plr]=e
    elseif e.highlight.Parent~=char then
        e.highlight.Parent=char
        e.billboard.Parent=head
    end
    e.highlight.FillColor=vars.espColor
    e.highlight.FillTransparency=0.5
    e.highlight.OutlineTransparency=0
    e.label.Text=string.format("%s  |  HP: %d/%d", plr.DisplayName~="" and plr.DisplayName or plr.Name, math.max(0,math.floor(hum.Health)), math.max(0,math.floor(hum.MaxHealth)))
    e.label.TextColor3=Color3.new(1,1,1)
end

