local function ESP()
    task.spawn(function()
        while states.espPlayers or states.espItems or states.espNPCs do
            pcall(function()
                if states.espPlayers then
                    for _,plr in ipairs(Players:GetPlayers()) do UpdatePlayerESP(plr) end
                else
                    for plr in pairs(ESPCache) do RemoveESP(plr) end
                end
                if states.espItems or states.espNPCs then
                    -- Keep the existing world ESP behavior, but only refresh it periodically.
                    for _,obj in ipairs(workspace:GetDescendants()) do
                        if states.espItems and obj:IsA("Tool") then
                            local h=obj:FindFirstChild("ESP_Highlight")
                            if not h then h=Instance.new("Highlight") h.Name="ESP_Highlight" h.FillColor=Color3.new(0,1,0) h.FillTransparency=0.5 h.Parent=obj end
                        elseif states.espNPCs and obj:IsA("Model") and obj:FindFirstChildOfClass("Humanoid") and not Players:GetPlayerFromCharacter(obj) then
                            local h=obj:FindFirstChild("ESP_Highlight")
                            if not h then h=Instance.new("Highlight") h.Name="ESP_Highlight" h.FillColor=Color3.new(1,0,0) h.FillTransparency=0.5 h.Parent=obj end
                        end
                    end
                end
            end)
            task.wait(0.25)
        end
        for plr in pairs(ESPCache) do RemoveESP(plr) end
    end)
end

