local function SpiderClimb()
    task.spawn(function()
        local last = 0
        while states.spiderClimb do
            if os.clock() - last > 0.03 then
                last = os.clock()
                pcall(function()
                    local c=Player.Character
                    local hrp=c and c:FindFirstChild("HumanoidRootPart")
                    local hum=c and c:FindFirstChildOfClass("Humanoid")
                    if hrp and hum then
                        local origin=hrp.Position
                        local dirs={hrp.CFrame.LookVector,-hrp.CFrame.RightVector,hrp.CFrame.RightVector}
                        local wall=nil
                        for _,dir in ipairs(dirs) do
                            local hit=workspace:Raycast(origin,dir*3.5)
                            if hit and hit.Instance and hit.Instance.CanCollide then wall=hit break end
                        end
                        if wall then
                            local move=hum.MoveDirection
                            local up=UIS:IsKeyDown(Enum.KeyCode.Space) and vars.spiderSpeed or 0
                            local down=UIS:IsKeyDown(Enum.KeyCode.LeftControl) and -vars.spiderSpeed or 0
                            hrp.AssemblyLinearVelocity=Vector3.new(
                                move.X*vars.spiderSpeed,
                                up+down,
                                move.Z*vars.spiderSpeed
                            )
                        end
                    end
                end)
            end
            task.wait()
        end
    end)
end

