local spiderWebHeld=false
local spiderTarget=nil

local function SpiderMan()
    task.spawn(function()
        local lastShot=0
        while states.spiderMan do
            pcall(function()
                local c=Player.Character
                local hrp=c and c:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                if not spiderTarget and os.clock()-lastShot>0.35 then
                    local params=RaycastParams.new()
                    params.FilterType=Enum.RaycastFilterType.Exclude
                    params.FilterDescendantsInstances={c}
                    local hit=workspace:Raycast(Camera.CFrame.Position,Camera.CFrame.LookVector*650,params)
                    if hit then
                        spiderTarget=hit.Position
                        lastShot=os.clock()
                        temp.webA0=Instance.new("Attachment",hrp)
                        temp.webA1=Instance.new("Attachment",workspace.Terrain)
                        temp.webA1.WorldPosition=spiderTarget
                        temp.web=Instance.new("Beam",workspace.Terrain)
                        temp.web.Attachment0=temp.webA0
                        temp.web.Attachment1=temp.webA1
                        temp.web.Width0=0.10
                        temp.web.Width1=0.035
                        temp.web.Segments=10
                        temp.web.FaceCamera=true
                        temp.web.Color=ColorSequence.new(Color3.fromRGB(235,235,235))
                    end
                end
                if spiderTarget then
                    local offset=spiderTarget-hrp.Position
                    local dist=offset.Magnitude
                    if dist>7 then
                        local dir=offset.Unit
                        local look=Camera.CFrame.LookVector
                        local swing=Vector3.new(look.X,math.max(look.Y,-0.05),look.Z)
                        if swing.Magnitude>0 then swing=swing.Unit end
                        local speed=math.max(vars.spiderSpeed,55)
                        local pull=math.clamp(dist*2.0,speed,speed*3.5)
                        local desired=dir*pull+swing*18+Vector3.new(0,8,0)
                        hrp.AssemblyLinearVelocity=hrp.AssemblyLinearVelocity:Lerp(desired,0.20)
                    else
                        hrp.AssemblyLinearVelocity=Camera.CFrame.LookVector*math.max(vars.spiderSpeed*1.7,85)+Vector3.new(0,20,0)
                        spiderTarget=nil
                        ClearWeb()
                    end
                else
                    local look=Camera.CFrame.LookVector
                    local desired=Vector3.new(look.X,math.max(look.Y,-0.15),look.Z).Unit*math.max(vars.spiderSpeed*0.8,40)+Vector3.new(0,8,0)
                    hrp.AssemblyLinearVelocity=hrp.AssemblyLinearVelocity:Lerp(desired,0.12)
                end
            end)
            RunService.Heartbeat:Wait()
        end
        spiderTarget=nil
        ClearWeb()
    end)
end


local function GetSpawnPart()
    local c=Player.Character
    local root=c and c:FindFirstChild("HumanoidRootPart")
    local candidates={}

    for _,obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("SpawnLocation") then
            table.insert(candidates,obj)
        elseif obj:IsA("BasePart") and obj.Name:lower():find("spawn") then
            table.insert(candidates,obj)
        end
    end

    local best=nil
    local bestScore=math.huge
    for _,part in ipairs(candidates) do
        local score=0
        if part:IsA("SpawnLocation") and Player.Team and part.TeamColor==Player.Team.TeamColor then
            score=-100000
        end
        if root then score=score+(part.Position-root.Position).Magnitude end
        if score<bestScore then bestScore=score best=part end
    end
    return best
end

local function TPSpawn()
    local c=Player.Character
    local hrp=c and c:FindFirstChild("HumanoidRootPart")
    local hum=c and c:FindFirstChildOfClass("Humanoid")
    if not hrp then return end

    local spawn=GetSpawnPart()
    if spawn then
        hrp.CFrame=spawn.CFrame+Vector3.new(0,5,0)
    elseif hum and hum.Health>0 then
        -- Если карта не содержит SpawnLocation, используем текущую точку респавна
        -- Roblox как fallback через SetPrimaryPartCFrame здесь не нужен.
        local last=Player:GetAttribute("PuskaLastSpawn")
        if typeof(last)=="CFrame" then hrp.CFrame=last+Vector3.new(0,5,0) end
    end
    hrp.AssemblyLinearVelocity=Vector3.zero
    hrp.AssemblyAngularVelocity=Vector3.zero
end

local FullBrightBackup=nil
local function SetFullBright(on)
    if on then
        if not FullBrightBackup then
            FullBrightBackup={
                Brightness=Lighting.Brightness,
                ClockTime=Lighting.ClockTime,
                FogEnd=Lighting.FogEnd,
                GlobalShadows=Lighting.GlobalShadows,
                Ambient=Lighting.Ambient,
                OutdoorAmbient=Lighting.OutdoorAmbient,
            }
        end
        Lighting.Brightness=2.5
        Lighting.ClockTime=14
        Lighting.FogEnd=100000
        Lighting.GlobalShadows=false
        Lighting.Ambient=Color3.fromRGB(180,180,180)
        Lighting.OutdoorAmbient=Color3.fromRGB(180,180,180)
    elseif FullBrightBackup then
        for k,v in pairs(FullBrightBackup) do Lighting[k]=v end
        FullBrightBackup=nil
    end
end

local function Homelander()
    task.spawn(function()
        local cooldown={}
        while states.homelander do
            pcall(function()
                local c=Player.Character
                local head=c and c:FindFirstChild("Head")
                if not head then return end

                if temp.laser1 then temp.laser1:Destroy() end
                temp.laser1=Instance.new("Beam")
                local a0=Instance.new("Attachment")
                a0.Parent=head
                local a1=Instance.new("Attachment")
                a1.WorldPosition=head.Position+Camera.CFrame.LookVector*150
                a1.Parent=workspace.Terrain
                temp.laser1.Attachment0=a0
                temp.laser1.Attachment1=a1
                temp.laser1.Width0=0.15
                temp.laser1.Width1=0.08
                temp.laser1.Color=ColorSequence.new(Color3.new(1,0,0))
                temp.laser1.Parent=workspace.Terrain

                for _,plr in ipairs(game:GetService("Players"):GetPlayers()) do
                    if IsEnemy(plr) and plr.Character then
                        local root=plr.Character:FindFirstChild("HumanoidRootPart")
                        if root and (root.Position-head.Position).Magnitude<150 then
                            local toTarget=(root.Position-head.Position).Unit
                            if toTarget:Dot(Camera.CFrame.LookVector)>0.94 then
                                local now=os.clock()
                                if not cooldown[plr] or now-cooldown[plr]>0.35 then
                                    cooldown[plr]=now
                                    root.AssemblyLinearVelocity=Camera.CFrame.LookVector*250+Vector3.new(0,80,0)
                                end
                            end
                        end
                    end
                end
                task.delay(0.08,function()
                    pcall(function() a0:Destroy(); a1:Destroy() end)
                end)
            end)
            task.wait(0.08)
        end
        if temp.laser1 then temp.laser1:Destroy() temp.laser1=nil end
    end)
end

