local function SerializeColor(c)
    return {r=math.floor(c.R*255),g=math.floor(c.G*255),b=math.floor(c.B*255)}
end
local function DeserializeColor(t)
    return Color3.fromRGB(tonumber(t.r) or 180,tonumber(t.g) or 180,tonumber(t.b) or 180)
end

local function CollectConfig()
    return {
        states=states,
        vars={
            flySpeed=vars.flySpeed,walkSpeed=vars.walkSpeed,spinSpeed=vars.spinSpeed,
            aimbotFOV=vars.aimbotFOV,spiderSpeed=vars.spiderSpeed
        },
        Settings={
            Theme=Settings.Theme,Language=Settings.Language,Scale=Settings.Scale,
            ConfigName=Settings.ConfigName,
            Ambience={
                Fog=Settings.Ambience.Fog,
                FogColor=SerializeColor(Settings.Ambience.FogColor),
                FogEnd=Settings.Ambience.FogEnd,
                Time=Settings.Ambience.Time
            }
        }
    }
end

local function ApplyConfig(data)
    if type(data)~="table" then return end
    if type(data.vars)=="table" then
        for k,v in pairs(data.vars) do if vars[k]~=nil and type(v)=="number" then vars[k]=v end end
    end
    if type(data.Settings)=="table" then
        if ThemeColors[data.Settings.Theme] then Settings.Theme=data.Settings.Theme end
        if data.Settings.Language=="Russian" or data.Settings.Language=="English" then Settings.Language=data.Settings.Language end
        if type(data.Settings.Scale)=="number" then Settings.Scale=math.clamp(data.Settings.Scale,0.5,1.5) end
        if type(data.Settings.Ambience)=="table" then
            local a=data.Settings.Ambience
            Settings.Ambience.Fog=not not a.Fog
            Settings.Ambience.FogEnd=tonumber(a.FogEnd) or 1000
            Settings.Ambience.Time=tonumber(a.Time) or 14
            if type(a.FogColor)=="table" then Settings.Ambience.FogColor=DeserializeColor(a.FogColor) end
        end
    end
end

local function SaveConfig(name)
    if not writefile then return false end
    name=tostring(name or Settings.ConfigName or "Default"):gsub("[^%w_%-]","_")
    local ok,encoded=pcall(function()
        return game:GetService("HttpService"):JSONEncode(CollectConfig())
    end)
    if not ok then return false end
    local path=(ConfigFolder and (ConfigFolder.."/"..name..".json")) or (name..".json")
    local ok2=pcall(function() writefile(path,encoded) end)
    if ok2 then Settings.ConfigName=name end
    return ok2
end

local function LoadConfig(name)
    if not readfile or not isfile then return false end
    name=tostring(name or "Default"):gsub("[^%w_%-]","_")
    local path=(ConfigFolder and (ConfigFolder.."/"..name..".json")) or (name..".json")
    if not isfile(path) then return false end
    local ok,data=pcall(function()
        return game:GetService("HttpService"):JSONDecode(readfile(path))
    end)
    if ok then ApplyConfig(data); Settings.ConfigName=name; return true end
    return false
end

local ambienceBackup=nil
local ambienceEffects={}

local function BackupAmbience()
    if ambienceBackup then return end
    ambienceBackup={ClockTime=Lighting.ClockTime,FogColor=Lighting.FogColor,FogStart=Lighting.FogStart,FogEnd=Lighting.FogEnd,Ambient=Lighting.Ambient,OutdoorAmbient=Lighting.OutdoorAmbient,Brightness=Lighting.Brightness,ExposureCompensation=Lighting.ExposureCompensation,GlobalShadows=Lighting.GlobalShadows,ColorShift_Top=Lighting.ColorShift_Top,ColorShift_Bottom=Lighting.ColorShift_Bottom}
end

local function RestoreAmbience()
    if not ambienceBackup then return end
    pcall(function()
        for k,v in pairs(ambienceBackup) do Lighting[k]=v end
    end)
    ambienceBackup=nil
end

local function ApplyAmbience()
    pcall(function()
        BackupAmbience()
        Lighting.ClockTime=math.clamp(tonumber(Settings.Ambience.Time) or 14,0,24)
        if Settings.Ambience.Fog then
            Lighting.FogColor=Settings.Ambience.FogColor
            Lighting.FogStart=0
            Lighting.FogEnd=math.max(50,tonumber(Settings.Ambience.FogEnd) or 1000)
        else
            Lighting.FogStart=0
            Lighting.FogEnd=100000
        end
    end)
end


-- === SHIRT / PHOTO CAPE ===
local CapeBase64=""

local function GetCustomAsset(path)
    local f=getcustomasset or getsynasset
    if f then
        local ok,result=pcall(f,path)
        if ok then return result end
    end
    return nil
end

local function DecodeBase64(data)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data=data:gsub('[^'..b..'=]','')
    return (data:gsub('.',function(x)
        if x=='=' then return '' end
        local r,f='',(b:find(x,1,true)-1)
        for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
        if #x~=8 then return '' end
        local c=0
        for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
end

local function EnsureCapeAsset()
    if not writefile then return nil end
    local ok=pcall(function()
        if not isfile or not isfile(capeAssetName) then
            local decode=(syn and syn.crypt and syn.crypt.base64decode)
                or (crypt and crypt.base64decode)
                or DecodeBase64
            writefile(capeAssetName,decode(CapeBase64))
        end
    end)
    if not ok then return nil end
    return GetCustomAsset(capeAssetName)
end

local function RemoveCape()
    for _,obj in ipairs({temp.capeGui,temp.capeWeld,temp.cape}) do
        pcall(function() if obj then obj:Destroy() end end)
    end
    temp.cape,temp.capeWeld,temp.capeGui=nil,nil,nil
end

local function CreateCape()
    RemoveCape()
    local c=Player.Character
    local hrp=c and c:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local asset=EnsureCapeAsset()
    if not asset then return end

    local cape=Instance.new("Part")
    cape.Name="PuskaPhotoCape"
    cape.Size=Vector3.new(4.4,5.2,0.12)
    cape.CanCollide=false
    cape.CanTouch=false
    cape.CanQuery=false
    cape.Massless=true
    cape.CastShadow=true
    cape.Transparency=0.02
    cape.Parent=c

    local weld=Instance.new("Weld")
    weld.Name="PuskaCapeWeld"
    weld.Part0=hrp
    weld.Part1=cape
    weld.C0=CFrame.new(0,0.35,1.45)
    weld.Parent=cape

    local gui=Instance.new("SurfaceGui")
    gui.Name="PuskaCapeImage"
    gui.Face=Enum.NormalId.Front
    gui.SizingMode=Enum.SurfaceGuiSizingMode.PixelsPerStud
    gui.PixelsPerStud=70
    gui.AlwaysOnTop=false
    gui.Parent=cape

    local image=Instance.new("ImageLabel")
    image.Size=UDim2.fromScale(1,1)
    image.BackgroundTransparency=1
    image.Image=asset
    image.ScaleType=Enum.ScaleType.Crop
    image.Parent=gui

    local back=gui:Clone()
    back.Face=Enum.NormalId.Back
    back.Parent=cape

    temp.cape=cape
    temp.capeWeld=weld
    temp.capeGui=gui
end

local function Shirt(on)
    states.shirt=on
    if on then
        CreateCape()
    else
        RemoveCape()
    end
end

