local function CreateTab(name,pos) local Tab=Instance.new("TextButton") Tab.Size=UDim2.new(1,-10,0,30) Tab.Position=UDim2.new(0,5,0,10+(pos-1)*40) Tab.Text=TabIcons[name].." "..T(name) Tab.BackgroundColor3=(ThemeColors[Settings.Theme].button or ThemeColors[Settings.Theme].main) Tab.TextColor3=ThemeColors[Settings.Theme].text Tab.Font=Enum.Font.Gotham Tab.TextSize=12 Tab.BorderSizePixel=0 Tab.AutoButtonColor=false Tab.Parent=TabFrame AddSmoothing(Tab,8) Tab.MouseEnter:Connect(function() SafeTween(Tab,TweenInfo.new(0.12),{BackgroundColor3=(ThemeColors[Settings.Theme].active or Color3.fromRGB(35,35,35))}) end) Tab.MouseLeave:Connect(function() SafeTween(Tab,TweenInfo.new(0.12),{BackgroundColor3=(name==CurrentTab and (ThemeColors[Settings.Theme].active or Color3.fromRGB(35,35,35)) or (ThemeColors[Settings.Theme].button or Color3.new(0,0,0)) )}) end) Tab.MouseButton1Click:Connect(function() CurrentTab=name UpdateTabs() ShowTab(name) end) Tabs[name]=Tab end
for i,name in ipairs(TabNames) do CreateTab(name,i) end

local TabContainers={} for _,name in ipairs(TabNames) do local c=Instance.new("ScrollingFrame") c.Size=UDim2.new(1,-20,1,-20) c.Position=UDim2.new(0,10,0,10) c.BackgroundTransparency=1 c.BorderSizePixel=0 c.ScrollBarThickness=2 c.AutomaticCanvasSize=Enum.AutomaticSize.Y c.CanvasSize=UDim2.new(0,0,0,0) c.Visible=false c.Parent=ContentFrame TabContainers[name]=c end
function ShowTab(name) for tn,c in pairs(TabContainers) do if tn==name then c.Visible=true else c.Visible=false end end end
function UpdateTabs() for name,tab in pairs(Tabs) do tab.BackgroundColor3=name==CurrentTab and Color3.fromRGB(30,30,30) or Color3.new(0,0,0) end end

local function CreateToggle(container,name,pos,callback) local T=Instance.new("TextButton") T.Size=UDim2.new(1,-20,0,35) T.Position=UDim2.new(0,10,0,10+pos) T.Text=name..": OFF" T.BackgroundColor3=(ThemeColors[Settings.Theme].button or Color3.fromRGB(25,25,25)) T.TextColor3=ThemeColors[Settings.Theme].text T.Font=Enum.Font.Gotham T.TextSize=13 T.BorderSizePixel=0 T.AutoButtonColor=false T.Parent=container AddSmoothing(T,6) local en=false
T.MouseButton2Click:Connect(function() bindingMode=true bindingTarget=name T.Text=name.." [KEY...]" task.delay(5,function() bindingMode=false T.Text=name..(en and ": ON" or ": OFF") end) end)
T.MouseButton1Click:Connect(function() if bindingMode then return end en=not en T.Text=name..(en and ": ON" or ": OFF") T.BackgroundColor3=en and (ThemeColors[Settings.Theme].active or Color3.fromRGB(45,45,45)) or (ThemeColors[Settings.Theme].button or Color3.new(0,0,0)) if callback then callback(en) end end) end

local function CreateSlider(container,name,min,max,default,pos,callback)
    local SF=Instance.new("Frame") SF.Size=UDim2.new(1,-20,0,50) SF.Position=UDim2.new(0,10,0,10+pos) SF.BackgroundColor3=Color3.new(0,0,0) SF.BorderSizePixel=0 SF.Parent=container AddSmoothing(SF,6)
    local L=Instance.new("TextLabel") L.Size=UDim2.new(1,-20,0,20) L.Position=UDim2.new(0,10,0,5) L.Text=name..": "..default L.BackgroundTransparency=1 L.TextColor3=Color3.new(1,1,1) L.Font=Enum.Font.Gotham L.TextSize=11 L.Parent=SF
    local BG=Instance.new("Frame") BG.Size=UDim2.new(1,-20,0,12) BG.Position=UDim2.new(0,10,0,30) BG.BackgroundColor3=Color3.fromRGB(30,30,30) BG.BorderSizePixel=0 BG.Parent=SF AddSmoothing(BG,6)
    local Fill=Instance.new("Frame") Fill.Size=UDim2.new(0.5,0,1,0) Fill.BackgroundColor3=(ThemeColors[Settings.Theme].accent or Color3.fromRGB(120,120,255)) Fill.BorderSizePixel=0 Fill.Parent=BG
    local Handle=Instance.new("Frame") Handle.Size=UDim2.new(0,14,0,14) Handle.Position=UDim2.new(0.5,-7,0.5,-7) Handle.BackgroundColor3=ThemeColors[Settings.Theme].text Handle.BorderSizePixel=0 Handle.Parent=BG
    local function Update() pcall(function() local mp=UIS:GetMouseLocation() local bp=BG.AbsolutePosition local bs=BG.AbsoluteSize local rx=math.clamp(mp.X-bp.X,0,bs.X) local pct=rx/bs.X local val=math.floor(min+(max-min)*pct) Fill.Size=UDim2.new(pct,0,1,0) Handle.Position=UDim2.new(pct,-7,0.5,-7) L.Text=name..": "..val if callback then callback(val) end end) end
    local dragging=false
    BG.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true Update() end end)
    UIS.InputChanged:Connect(function(input) if dragging and input.UserInputType==Enum.UserInputType.MouseMovement then Update() end end)
    UIS.InputEnded:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end end)
end


