local LangBtn=Instance.new("TextButton") LangBtn.Size=UDim2.new(1,-20,0,40) LangBtn.Position=UDim2.new(0,10,0,60) LangBtn.Text=T("Language") LangBtn.BackgroundColor3=Color3.new(0,0,0) LangBtn.TextColor3=Color3.new(1,1,1) LangBtn.Font=Enum.Font.GothamBold LangBtn.TextSize=14 LangBtn.BorderSizePixel=0 LangBtn.Parent=SC LangBtn.MouseButton1Click:Connect(function() Settings.Language=Settings.Language=="English" and "Russian" or "English" UpdateLanguage() end)
CreateSlider(SC,"Scale",50,150,100,110,function(v) Settings.Scale=v/100 MF.Size=UDim2.new(0,600*Settings.Scale,0,400*Settings.Scale) end)

function UpdateTheme() local theme=ThemeColors[Settings.Theme] or ThemeColors.Black MF.BackgroundColor3=theme.main TB.BackgroundColor3=theme.main TabFrame.BackgroundColor3=theme.main ContentFrame.BackgroundColor3=theme.main Title.TextColor3=theme.text for name,tab in pairs(Tabs) do tab.TextColor3=theme.text tab.BackgroundColor3=(name==CurrentTab and (theme.active or theme.main) or (theme.button or theme.main)) end for _,obj in ipairs(SG:GetDescendants()) do if obj:IsA("TextButton") then obj.TextColor3=theme.text elseif obj:IsA("Frame") and obj.Name=="Fill" then obj.BackgroundColor3=theme.accent or obj.BackgroundColor3 end end end
function UpdateLanguage() for name,tab in pairs(Tabs) do tab.Text=TabIcons[name].." "..T(name) end ThemeBtn.Text=T("Theme") LangBtn.Text=T("Language") end

local function ToggleMenu(v) if v then MF.Visible=true MF.Size=UDim2.new(0,0,0,0) MF.Position=UDim2.new(0.5,0,0.5,0) SafeTween(MF,TweenInfo.new(0.5,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Size=UDim2.new(0,600*Settings.Scale,0,400*Settings.Scale),Position=UDim2.new(0.5,-300*Settings.Scale,0.5,-200*Settings.Scale)}) else SafeTween(MF,TweenInfo.new(0.3,Enum.EasingStyle.Quad,Enum.EasingDirection.In),{Size=UDim2.new(0,0,0,0),Position=UDim2.new(0.5,0,0.5,0)}) task.wait(0.3) MF.Visible=false MF.Size=UDim2.new(0,600*Settings.Scale,0,400*Settings.Scale) MF.Position=UDim2.new(0.5,-300*Settings.Scale,0.5,-200*Settings.Scale) end end

