UIS.InputBegan:Connect(function(input,processed)
    if processed then return end
    if states.playerTP and input.UserInputType==Enum.UserInputType.MouseButton2 then
        pcall(function()
            local mouse=Player:GetMouse()
            local target=mouse.Target
            local model=target and target:FindFirstAncestorOfClass("Model")
            local targetPlayer=model and game:GetService("Players"):GetPlayerFromCharacter(model)
            local myRoot=Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
            local targetRoot=targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            if myRoot and targetRoot then
                myRoot.CFrame=targetRoot.CFrame*CFrame.new(0,0,3)
                myRoot.AssemblyLinearVelocity=Vector3.zero
            end
        end)
        return
    end
    if input.KeyCode==Enum.KeyCode.RightShift then ToggleMenu(not MF.Visible) return end if bindingMode and bindingTarget then if input.KeyCode and input.KeyCode~=Enum.KeyCode.Unknown then bindings[bindingTarget]=input.KeyCode bindingMode=false bindingTarget=nil return end end for fn,key in pairs(bindings) do if key==input.KeyCode then if fn=="Aimbot" then states.aimbot=not states.aimbot if states.aimbot then Aimbot() end elseif fn=="Fly" then states.flying=not states.flying elseif fn=="Spin" then states.spin=not states.spin if states.spin then Spin() end end end end end)

task.spawn(function() while true do pcall(function() if TimeLabel then local d=os.date("*t") TimeLabel.Text=string.format("%02d:%02d:%02d",d.hour,d.min,d.sec) end end) task.wait(1) end end)

RunService.RenderStepped:Connect(function(dt)
    if fovCircle and fovCircle.Visible then
        fovCircle.Position=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y/2)
    end

    if states.spin then
        pcall(function()
            local c=Player.Character
            local hrp=c and c:FindFirstChild("HumanoidRootPart")
            if hrp then
                hrp.CFrame=hrp.CFrame*CFrame.Angles(0,math.rad(vars.spinSpeed)*dt,0)
            end
        end)
    end

    if states.targetLock or states.orbitTarget or states.targetESP then
        pcall(function()
            local c=Player.Character
            local my=c and c:FindFirstChild("HumanoidRootPart")
            if not my then return end
            local best,bestDist=nil,math.huge
            for _,plr in ipairs(game:GetService("Players"):GetPlayers()) do
                if IsEnemy(plr) and plr.Character then
                    local root=plr.Character:FindFirstChild("HumanoidRootPart")
                    local hum=plr.Character:FindFirstChildOfClass("Humanoid")
                    if root and hum and hum.Health>0 then
                        local d=(root.Position-my.Position).Magnitude
                        if d<bestDist and d<300 then best,bestDist=root,d end
                    end
                end
            end

            if states.targetESP then
                for _,plr in ipairs(game:GetService("Players"):GetPlayers()) do
                    if IsEnemy(plr) and plr.Character then
                        local old=plr.Character:FindFirstChild("PuskaTargetHighlight")
                        if old then old:Destroy() end
                    end
                end
                if best and best.Parent then
                    local hl=Instance.new("Highlight")
                    hl.Name="PuskaTargetHighlight"
                    hl.Adornee=best.Parent
                    hl.FillTransparency=0.75
                    hl.OutlineTransparency=0.05
                    hl.Parent=best.Parent
                end
            end

            if best then
                if states.targetLock then
                    Camera.CFrame=CFrame.lookAt(Camera.CFrame.Position,best.Position)
                end
                if states.orbitTarget then
                    local t=os.clock()*math.max(0.1,vars.orbitSpeed)
                    local p=best.Position+Vector3.new(math.cos(t)*vars.orbitRadius,2,math.sin(t)*vars.orbitRadius)
                    my.AssemblyLinearVelocity=(p-my.Position)*3.0
                end
            end
        end)
    end

    if states.flying and temp.bv and temp.bg then
        pcall(function()
            local cam=Camera.CFrame
            temp.bg.CFrame=cam
            local d=Vector3.zero
            if UIS:IsKeyDown(Enum.KeyCode.W) then d+=cam.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.S) then d-=cam.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.A) then d-=cam.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.D) then d+=cam.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then d+=Vector3.new(0,1,0) end
            if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then d-=Vector3.new(0,1,0) end
            temp.bv.Velocity=d.Magnitude>0 and d.Unit*vars.flySpeed or Vector3.zero
        end)
    end

    if states.shirt and temp.capeWeld then
        pcall(function()
            local wave=math.sin(os.clock()*5)*0.18
            local sway=math.cos(os.clock()*3.5)*0.10
            temp.capeWeld.C0=CFrame.new(0,0.35,1.45)*CFrame.Angles(wave,sway,0)
        end)
    end
end)

task.spawn(function() while task.wait(0.2) do if states.noDamage then pcall(function() local c=Player.Character if c then local h=c:FindFirstChildOfClass("Humanoid") if h and h.Health>0 then h.Health=h.MaxHealth end end end) end end end)
task.spawn(function() while task.wait(1) do if states.speedHack then pcall(function() local c=Player.Character if c then local h=c:FindFirstChildOfClass("Humanoid") if h and not states.flying then h.WalkSpeed=vars.walkSpeed end end end) end end end)

