-- Spider-Man 3D pull
local function GetSpiderPosition(target)
    if not target or not target.Parent then return nil end
    if target:IsA("BasePart") then return target.Position end
    if target:IsA("Model") then
        local root=target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart",true)
        return root and root.Position or nil
    end
    return nil
end
local SpiderActive=false
local SpiderTarget=nil
local SpiderConnection=nil
function StopSpiderMan()
    SpiderActive=false
    SpiderTarget=nil
    if SpiderConnection then SpiderConnection:Disconnect(); SpiderConnection=nil end
end
function SpiderToTarget(target)
    local char=Player.Character
    local hrp=char and char:FindFirstChild("HumanoidRootPart")
    if not hrp or not GetSpiderPosition(target) then return end
    StopSpiderMan()
    SpiderActive=true
    SpiderTarget=target
    SpiderConnection=RunService.Heartbeat:Connect(function()
        if not SpiderActive then return end
        local c=Player.Character
        local r=c and c:FindFirstChild("HumanoidRootPart")
        local pos=GetSpiderPosition(SpiderTarget)
        if not r or not pos then StopSpiderMan(); return end
        local delta=pos-r.Position
        local d=delta.Magnitude
        if d<=4 then r.AssemblyLinearVelocity=Vector3.zero; StopSpiderMan(); return end
        r.AssemblyLinearVelocity=delta.Unit*math.clamp(85+d*2.2,85,360)
    end)
end

-- V2 lifecycle / cleanup
local V2Connections = {}

table.insert(V2Connections, Player.CharacterAdded:Connect(function(character)
    task.wait(0.5)
    pcall(function()
        local root=character:FindFirstChild("HumanoidRootPart")
        if root then Player:SetAttribute("PuskaLastSpawn",root.CFrame) end
    end)
    -- Сбрасываем временные объекты после респавна.
    pcall(function()
        if temp.bv then temp.bv:Destroy(); temp.bv=nil end
        if temp.bg then temp.bg:Destroy(); temp.bg=nil end
        ClearWeb()
        if temp.dildak then temp.dildak:Destroy(); temp.dildak=nil end
        if temp.laser1 then temp.laser1:Destroy(); temp.laser1=nil end
    end)
    states.flying = false
    if states.shirt then task.wait(0.2) CreateCape() end
end))

local function CleanupPuska()
    for _, c in ipairs(V2Connections) do pcall(function() c:Disconnect() end) end
    for k, obj in pairs(temp) do
        pcall(function() if obj and typeof(obj) == "Instance" then obj:Destroy() end end)
        temp[k] = nil
    end
    if fovCircle then pcall(function() fovCircle:Remove() end) end
    pcall(function() SetFullBright(false) end)
    pcall(function() SG:Destroy() end)
end

Close.MouseButton1Click:Connect(function()
    CleanupPuska()
end)

